using System;
using System.Linq;
using System.Collections.Generic;
namespace LittleNotebook {public partial class MainWindow {
 void RunGenerationChecks(Action<bool,string> check){
  foreach(int count in new[]{1,2,5,10,15,31})foreach(string[] topics in new[]{new[]{"english"},new[]{"english","math"},PlayTopics})for(int pass=0;pass<8;pass++){
   var stream=new QuestionStream(bank,topics,3,new Attempt[0],new Dictionary<string,string>(),count);var questions=Enumerable.Range(0,count).Select(i=>stream.Next()).ToList();var difficulty=Enumerable.Range(0,3).Select(l=>questions.Count(q=>q.Difficulty==l)).ToArray();check(difficulty.Max()-difficulty.Min()<=1,"Mixed quota imbalance");var sizes=topics.Select(t=>questions.Count(q=>q.Topic==t)).ToArray();check(sizes.Max()-sizes.Min()<=1,"Topic quota imbalance");foreach(string topic in topics){var types=QuestionCatalog.Categories(bank,topic,3).Where(c=>c!="all");var amounts=types.Select(c=>questions.Count(q=>q.Topic==topic&&QuestionCatalog.Category(q)==c)).ToArray();check(amounts.Max()-amounts.Min()<=1,"Type quota imbalance");}
   foreach(var q in questions){var round=new GameSession(3){Questions=new List<Question>{q}};check(round.Limit>0&&round.Answer(q.Answer,false).Difficulty==q.Difficulty,"Mixed timer/scoring level failed");}
  }
  var history=new[]{new Attempt{Id="known",Correct=true},new Attempt{Id="known",Correct=true},new Attempt{Id="wrong",Correct=false}};check(QuestionStream.HistoryWeight(history,"wrong")>QuestionStream.HistoryWeight(history,"new")&&QuestionStream.HistoryWeight(history,"new")>QuestionStream.HistoryWeight(history,"known")&&QuestionStream.HistoryWeight(history,"known")>0,"Repeat weights incorrect");
  selectedTopic="mixed";ToggleTopic("math");check(SelectedTopics.Length==3&&!SelectedTopics.Contains("math"),"All minus topic failed");ToggleTopic("math");check(selectedTopic=="mixed","All topic restoration failed");
  var factory=new WordSearchFactory(new Random(184));int diagonal=0,multiple=0;var locations=new HashSet<int>();foreach(int level in new[]{0,1,2})for(int pass=0;pass<100;pass++){var board=factory.Create("MOON",new[]{"STAR","TREE","BOOK","SUN"},level);check(board.Words.Length==board.Paths.Length&&board.Words.Length>=1,"Missing search path");for(int i=0;i<board.Words.Length;i++){check(new string(board.Paths[i].Select(cell=>board.Letters[cell]).ToArray())==board.Words[i],"Corrupt search word");var path=board.Paths[i];int step=path[1]-path[0];if(Math.Abs(step)==7||Math.Abs(step)==9)diagonal++;if(level==0)check(Math.Abs(step)==1||Math.Abs(step)==8,"Easy diagonal");locations.Add(path[0]);}if(board.Words.Length>1)multiple++;}
  check(diagonal>30&&multiple>50&&locations.Count>35,"Search generation insufficient variety");
  game=new GameSession(2){Topic="puzzles",Questions=new List<Question>{bank.Questions.First(q=>q.Kind=="search"&&q.Difficulty==2)}};page="game";interactionId="";Build();check(questionSpeaker==null,"Word search speaker displayed");foreach(var path in searchBoard.Paths.ToArray())foreach(int cell in path)SelectSearch(cell);check(game.Answered&&Profile.Attempts.Last().Correct,"Search did not auto-complete");check(Profile.Attempts.Last().LayoutJson.Contains("SearchWords"),"Search targets not saved");Capture("r4-multiword-search");game=null;Profile.Attempts.Clear();page="home";Profile.Settings.Difficulty=3;Build();Capture("r4-mixed-topics");Profile.Settings.Difficulty=0;
 }
}}
